// =====================================================================
//  CLIENTE DE IA (único punto del sistema que habla con el modelo)
//
//  Entrada: { tarea, sistema, mensaje, esquema, max_tokens? }
//  El proveedor se elige en el .env, sin tocar este workflow:
//    AI_PROVIDER=anthropic -> API de Mensajes de Claude
//    AI_PROVIDER=openai    -> cualquier API compatible con OpenAI
//                             (Ollama, LM Studio, vLLM, Groq...)
//  La API key no pasa por aquí: la agrega la credencial del nodo HTTP.
// =====================================================================
const entrada = $input.first().json;
const proveedor = String($env.AI_PROVIDER || 'anthropic').trim().toLowerCase();
const sinConfigurar = (motivo) => [{ json: { proveedor, modelo: $env.AI_MODEL || null, errorConfig: motivo } }];

if (!entrada.sistema || !entrada.mensaje || !entrada.esquema) {
  return sinConfigurar('La petición a la IA está incompleta (se requieren sistema, mensaje y esquema).');
}

if (proveedor === 'anthropic') {
  if (!$env.AI_API_KEY) return sinConfigurar('Falta AI_API_KEY en el archivo .env del backend.');
  const base = String($env.AI_BASE_URL || 'https://api.anthropic.com').replace(/\/+$/, '');
  const modelo = $env.AI_MODEL || 'claude-opus-5-5';
  const esfuerzo = String($env.AI_EFFORT ?? 'low').trim();

  const cuerpo = {
    model: modelo,
    max_tokens: entrada.max_tokens ?? 16000,
    system: entrada.sistema,
    messages: [{ role: 'user', content: entrada.mensaje }],
    // Salida estructurada: la API garantiza un JSON que cumple el esquema
    output_config: { format: { type: 'json_schema', schema: entrada.esquema } },
  };
  // El esfuerzo controla cuánto razona el modelo (low = respuestas rápidas)
  if (esfuerzo && esfuerzo !== 'none') cuerpo.output_config.effort = esfuerzo;

  const encabezados = { 'anthropic-version': '2023-06-01' };
  // Si el modelo rechaza la solicitud por sus políticas, la API la reintenta
  // en el modelo de respaldo recomendado (ANTHROPIC_FALLBACKS=none lo desactiva)
  if (String($env.ANTHROPIC_FALLBACKS ?? 'default').trim() === 'default') {
    cuerpo.fallbacks = 'default';
    encabezados['anthropic-beta'] = 'server-side-fallback-2026-07-01';
  }
  return [{ json: { proveedor, modelo, url: `${base}/v1/messages`, encabezados, cuerpo } }];
}

if (proveedor === 'openai') {
  const base = String($env.AI_BASE_URL || 'http://host.docker.internal:11434/v1').replace(/\/+$/, '');
  const modelo = $env.AI_MODEL || 'llama3.2';
  const modoJson = String($env.AI_JSON_MODE || 'json_schema').trim();

  const cuerpo = {
    model: modelo,
    temperature: 0.2,
    stream: false,
    messages: [
      { role: 'system', content: entrada.sistema },
      { role: 'user', content: entrada.mensaje },
    ],
  };
  if (modoJson === 'json_schema') {
    cuerpo.response_format = {
      type: 'json_schema',
      json_schema: { name: entrada.tarea || 'respuesta', strict: true, schema: entrada.esquema },
    };
  } else if (modoJson === 'json_object') {
    cuerpo.response_format = { type: 'json_object' };
  }
  return [{ json: { proveedor, modelo, url: `${base}/chat/completions`, encabezados: {}, cuerpo } }];
}

return sinConfigurar(`AI_PROVIDER="${proveedor}" no es válido. Usa "anthropic" u "openai".`);

// =====================================================================
//  Normaliza la respuesta de cualquier proveedor a un único formato:
//    { ok: true,  datos: <JSON del modelo>, proveedor, modelo, uso }
//    { ok: false, error: <mensaje claro>,   proveedor, modelo, detalle }
//  Los workflows que llaman a la IA nunca ven el formato del proveedor.
// =====================================================================
const peticion = $('Construir petición').first().json;
const base = { proveedor: peticion.proveedor, modelo: peticion.modelo };
const fallo = (error, detalle = null) => [{ json: { ok: false, ...base, error, detalle } }];

if (peticion.errorConfig) return fallo('La IA no está configurada', peticion.errorConfig);

const respuesta = $input.first().json;

// Error de red o tiempo de espera agotado (el nodo HTTP continúa con { error })
if (respuesta.statusCode === undefined) {
  const e = respuesta.error ?? {};
  const motivo = typeof e === 'string' ? e : e.message || e.code || JSON.stringify(e);
  return fallo('No fue posible comunicarse con el proveedor de IA', String(motivo).slice(0, 300));
}

const cuerpo = respuesta.body ?? {};
if (respuesta.statusCode >= 400) {
  const motivo = cuerpo?.error?.message ?? cuerpo?.message ?? JSON.stringify(cuerpo);
  return fallo(`El proveedor de IA respondió con error HTTP ${respuesta.statusCode}`, String(motivo).slice(0, 300));
}

let textoModelo = '';
if (peticion.proveedor === 'anthropic') {
  // La respuesta puede traer bloques de razonamiento antes del texto final
  if (cuerpo.stop_reason === 'refusal') {
    return fallo('El modelo se negó a responder esta solicitud', cuerpo.stop_details?.explanation ?? null);
  }
  if (cuerpo.stop_reason === 'max_tokens') return fallo('La respuesta del modelo quedó incompleta (límite de tokens)');
  textoModelo = (cuerpo.content ?? []).filter((bloque) => bloque.type === 'text').map((bloque) => bloque.text).join('');
} else {
  const opcion = cuerpo.choices?.[0];
  if (opcion?.finish_reason === 'length') return fallo('La respuesta del modelo quedó incompleta (límite de tokens)');
  textoModelo = opcion?.message?.content ?? '';
}

// Extrae el JSON aunque el modelo lo envuelva en ```json ... ```
function extraerJson(valor) {
  const t = String(valor).trim();
  const candidatos = [t, t.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, ''), t.slice(t.indexOf('{'), t.lastIndexOf('}') + 1)];
  for (const candidato of candidatos) {
    try {
      const datos = JSON.parse(candidato);
      if (datos && typeof datos === 'object' && !Array.isArray(datos)) return datos;
    } catch {
      // se intenta con el siguiente candidato
    }
  }
  return null;
}

const datos = extraerJson(textoModelo);
if (!datos) return fallo('La IA no devolvió un JSON válido', String(textoModelo).slice(0, 300));

return [{ json: { ok: true, ...base, modelo: cuerpo.model ?? base.modelo, datos, uso: cuerpo.usage ?? null } }];
